INSERT INTO `ingest_staging` VALUES (1711,'LOAD','LOADER-001','DEMO-1791551722482','2026-10-09 21:15:22','2026-10-09 21:15:22','{\"batchNos\": [\"SP20261009-001-05\"], \"loadTime\": \"2026-10-09 21:15:21\", \"driverName\": \"张师傅\"}','LOADER-001',3,'cold_chain_transport',NULL,'缺少车牌号(vehicleNo)：装车口必须先识别到车牌才能生成运单',NULL,NULL,NULL,'2026-10-09 21:15:22'),(1712,'LOAD','LOADER-001','DEMO-1791551722582','2026-10-09 21:15:23','2026-10-09 21:15:23','{\"loadTime\": \"2026-10-09 21:15:20\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\"}','LOADER-001',3,'cold_chain_transport',NULL,'缺少装车批次号(batchNos)：扫码枪须扫出本车装载的分割批次，系统才能倒查出发货计划',NULL,NULL,NULL,'2026-10-09 21:15:23'),(1713,'LOAD','LOADER-001','DEMO-1791551722641','2026-10-09 21:15:23','2026-10-09 21:15:23','{\"batchNos\": [\"SP20261009-001-05\"], \"loadTime\": \"2026-10-09 21:15:19\", \"vehicleNo\": \"京A·12345\"}','LOADER-001',1,'cold_chain_transport',NULL,'现场没读到司机。按车牌 京A·12345 反查备案的常用司机是「张师傅」—— 这只是推定、未经本人确认，请司机刷卡确认，或人工核对后补录',NULL,NULL,NULL,'2026-10-09 21:15:23'),(1714,'LOAD','LOADER-001','DEMO-1791551722776','2026-10-09 21:15:23','2026-10-09 21:15:23','{\"cardNo\": \"9999\", \"batchNos\": [\"SP-TEST-0003\"], \"loadTime\": \"2026-10-09 21:15:18\", \"vehicleNo\": \"京A·12345\"}','LOADER-001',1,'cold_chain_transport',NULL,'司机卡「9999」没有登记在司机备案里，无法确认持卡人是谁，请先在司机备案中登记该卡，或由司机改用姓名登记后重报',NULL,NULL,NULL,'2026-10-09 21:15:23'),(1715,'LOAD','LOADER-001','DEMO-1791551722852','2026-10-09 21:15:23','2026-10-09 21:15:23','{\"cardNo\": \"8801\", \"batchNos\": [\"SP-TEST-0003\"], \"loadTime\": \"2026-10-09 21:15:17\", \"vehicleNo\": \"京A·12345\"}','LOADER-001',1,'cold_chain_transport',NULL,'扫到的货物（SP-TEST-0003）不属于任何待发货计划，无法确定该发去哪家店。装车口不猜目的地，请先建发货计划后重新扫码，或走人工建单',NULL,NULL,NULL,'2026-10-09 21:15:23'),(1716,'LOAD','LOADER-001','DEMO-1791551722936','2026-10-09 21:15:23','2026-10-09 21:15:23','{\"batchNos\": [\"SP20261009-001-02\"], \"loadTime\": \"2026-10-09 21:15:16\", \"vehicleNo\": \"京A·88888\", \"driverName\": \"李四\"}','LOADER-001',1,'cold_chain_transport',NULL,'装车口自动建单未通过：装车口识别的车牌号「京A·88888」与计划安排的「京A·99999」不一致，请人工核对是否装错车',NULL,NULL,NULL,'2026-10-09 21:15:23'),(1717,'LOAD','LOADER-001','DEMO-1791551723037','2026-10-09 21:15:23','2026-10-09 21:15:23','{\"cardNo\": \"8801\", \"batchNos\": [\"SP20261009-001-05\", \"SP20261009-001-04\", \"SP20261009-001-03\"], \"loadTime\": \"2026-10-09 21:15:16\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\", \"driverPhone\": \"13700000002\"}','LOADER-001',2,'cold_chain_transport',66,NULL,NULL,NULL,NULL,'2026-10-09 21:15:23'),(1718,'LOAD','LOADER-001','DEMO-1791551723191','2026-10-09 21:15:23','2026-10-09 21:15:23','{\"batchNos\": [\"SP20261009-001-05\"], \"loadTime\": \"2026-10-09 21:15:15\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\"}','LOADER-001',3,'cold_chain_transport',NULL,'分割批次 SP20261009-001-05 已由运单发运过，禁止重复装车（如确需重发请人工核对后处理）',NULL,NULL,NULL,'2026-10-09 21:15:23'),(1719,'LOAD','LOADER-001','DEMO-1791551723245','2026-10-09 21:15:23','2026-10-09 21:15:23','{\"batchNos\": [\"SP20261009-001-02\", \"SP20261009-001-01\"], \"loadTime\": \"2026-10-09 21:15:14\", \"vehicleNo\": \"京A·99999\", \"driverName\": \"李四\"}','LOADER-001',2,'cold_chain_transport',67,NULL,NULL,NULL,NULL,'2026-10-09 21:15:23'),(1720,'LOAD','LOADER-001','DEMO-1791551723348','2026-10-09 21:15:23','2026-10-09 21:15:23','{\"batchNos\": [\"SP20261003286878\"], \"loadTime\": \"2026-10-09 21:15:13\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\"}','LOADER-001',2,'cold_chain_transport',68,NULL,NULL,NULL,NULL,'2026-10-09 21:15:23'),(1721,'LOAD','LOADER-001','DEMO-1791551723502','2026-10-09 21:15:24','2026-10-09 21:15:24','{\"cardNo\": \"8801\", \"batchNos\": [\"SP-TEST-0001\"], \"loadTime\": \"2026-10-09 21:15:12\", \"vehicleNo\": \"京A·12345\"}','LOADER-001',2,'cold_chain_transport',69,NULL,NULL,NULL,NULL,'2026-10-09 21:15:24');
